import os
from pathlib import Path

root = Path(os.environ['ANDROID_DIR']) / 'app/src/main/assets/www'
index = root / 'index.html'
if not index.exists():
    raise SystemExit('index.html nao encontrado')

# Copia as artes de referência já versionadas no repositório para dentro do APK.
repo = Path(os.environ['GITHUB_WORKSPACE'])
assets = repo / '.github/assets'
for src_name, dst_name in [
    ('matchscore-rpg-hero.jpg', 'rpg-hero-v27.jpg'),
    ('matchscore-rpg-catalog.jpg', 'rpg-catalog-v27.jpg'),
    ('matchscore-rpg-progression.jpg', 'rpg-progression-v27.jpg'),
]:
    src = assets / src_name
    if src.exists():
        (root / dst_name).write_bytes(src.read_bytes())

css = r'''
:root{--ms-bg:#06111e;--ms-panel:#0b1929;--ms-panel2:#0d1e31;--ms-line:#203a56;--ms-text:#f6f9fc;--ms-muted:#93a8bf;--ms-green:#22e4b0;--ms-cyan:#2ab4ff;--ms-gold:#f5c65a;--ms-purple:#bd66ff}
#msRpg27{position:fixed;inset:0;z-index:2147483600;overflow:auto;color:var(--ms-text);font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:radial-gradient(circle at 90% -5%,#1c4f7d55 0,transparent 34%),radial-gradient(circle at 0 30%,#0ec99a20 0,transparent 26%),linear-gradient(180deg,#071523,#06111e 42%,#050d17);padding-bottom:max(24px,env(safe-area-inset-bottom));}
#msRpg27 *{box-sizing:border-box}#msRpg27 button{font:inherit;color:inherit}
.r27-shell{max-width:820px;margin:auto;min-height:100%}.r27-top{position:sticky;top:0;z-index:50;padding:14px 16px 11px;background:linear-gradient(180deg,#071523f5 78%,#071523c8 88%,transparent);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}
.r27-brand{display:flex;align-items:center;gap:10px}.r27-logo{width:43px;height:43px;border-radius:13px;display:grid;place-items:center;font-weight:1000;font-size:21px;color:#032019;background:linear-gradient(145deg,#32f0bd,#1ab0ff);box-shadow:0 10px 34px #17cbb955,inset 0 1px #ffffff88}.r27-brandtext b{display:block;font-size:19px;letter-spacing:-.035em}.r27-brandtext small{color:#8fa6bd;font-size:11px}.r27-wallet{margin-left:auto;display:flex;align-items:center;gap:7px;padding:8px 11px;border:1px solid #2a4664;border-radius:999px;background:linear-gradient(180deg,#102238,#0b1828);font-weight:850;box-shadow:inset 0 1px #ffffff0b}.r27-coin{width:18px;height:18px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff7ba 0 16%,#f9ce58 18% 48%,#c38813 50% 70%,#704708 72%);box-shadow:0 0 13px #f4c04c55}
.r27-headline{display:flex;align-items:center;gap:10px;margin-top:15px}.r27-headline h1{margin:0;font-size:29px;letter-spacing:-.045em;font-weight:950}.r27-badge{padding:7px 10px;border-radius:999px;background:linear-gradient(135deg,#2ce9b6,#17c08e);color:#02251b;font-weight:950;font-size:12px;box-shadow:0 7px 24px #17d79f33}.r27-close{margin-left:auto;width:43px;height:43px;border:1px solid #2b435f;border-radius:14px;background:linear-gradient(180deg,#102036,#0b1727);font-size:23px;box-shadow:inset 0 1px #ffffff10}
.r27-tabs{display:flex;gap:8px;overflow:auto;padding:9px 16px 15px;scrollbar-width:none;border-bottom:1px solid #142a3f}.r27-tabs::-webkit-scrollbar{display:none}.r27-tab{white-space:nowrap;border:1px solid #2a415b;border-radius:14px;padding:11px 15px;background:linear-gradient(180deg,#0e1c2e,#0a1625);color:#9db0c5;font-weight:850;box-shadow:inset 0 1px #ffffff08}.r27-tab.on{color:white;border-color:#32e9ba;background:linear-gradient(135deg,#109176,#1ac49a);box-shadow:0 9px 28px #0ec59731,inset 0 1px #8effdd55}
.r27-body{padding:16px}.r27-card{border:1px solid #223d58;background:linear-gradient(180deg,#0d1d30,#091624);border-radius:24px;box-shadow:0 22px 60px #0008,inset 0 1px #ffffff08}.r27-panel{display:none}.r27-panel.on{display:block}
.r27-hero{position:relative;min-height:650px;overflow:hidden;background:#081624}.r27-heroart{position:absolute;inset:0;background-image:linear-gradient(180deg,#06111e05 45%,#06111e55 65%,#06111ef6 92%),linear-gradient(90deg,#06111e80 0,#06111e10 43%,#06111e45 100%),url('rpg-hero-v27.jpg');background-size:cover;background-position:center 40%;filter:saturate(1.08) contrast(1.05)}.r27-hero:after{content:'';position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 95px #020813b8}.r27-scan{position:absolute;inset:0;opacity:.16;background-image:linear-gradient(#fff1 1px,transparent 1px),linear-gradient(90deg,#fff1 1px,transparent 1px);background-size:28px 28px;mask-image:linear-gradient(transparent,#000 15%,#000 70%,transparent)}
.r27-level{position:absolute;left:15px;top:15px;z-index:3;min-width:124px;padding:12px 13px;border:1px solid #34536f;border-radius:17px;background:#071522d9;backdrop-filter:blur(10px);box-shadow:0 12px 30px #0005}.r27-level small{color:#9cb0c5}.r27-level b{display:block;font-size:38px;line-height:1;margin-top:3px}.r27-equipped{position:absolute;right:15px;top:15px;z-index:3;width:155px;padding:11px;border:1px solid #8b681b;border-radius:17px;background:#10150edb;backdrop-filter:blur(10px);box-shadow:0 12px 30px #0005}.r27-equipped small{color:#b7bdc2;font-size:10px}.r27-equipped b{display:block;margin-top:3px;font-size:13px;line-height:1.2}.r27-rarity{display:inline-block;margin-top:7px;padding:4px 7px;border-radius:999px;background:#674a0b;color:#ffdb73;font-weight:950;font-size:10px}
.r27-stats{position:absolute;left:14px;bottom:115px;z-index:3;display:grid;gap:8px}.r27-stat{width:95px;padding:9px 11px;border:1px solid #2b4967;border-radius:14px;background:#071522dc;backdrop-filter:blur(9px);box-shadow:0 8px 20px #0004}.r27-stat span{display:block;color:#8fa8c0;font-size:9px;font-weight:850}.r27-stat b{font-size:22px}.r27-stat.for b{color:#ff6676}.r27-stat.def b{color:#70b7ff}.r27-stat.vel b{color:#55e4b0}.r27-stat.mag b{color:#d58aff}.r27-boost{position:absolute;right:14px;bottom:118px;z-index:3;padding:11px 14px;border:1px solid #159878;border-radius:17px;background:#062a23df;text-align:center;backdrop-filter:blur(9px)}.r27-boost small{color:#a6c6bd}.r27-boost b{display:block;color:#30efb7;font-size:23px}.r27-xpbox{position:absolute;left:14px;right:14px;bottom:16px;z-index:3;padding:12px 13px;border:1px solid #2c4965;border-radius:17px;background:#071522e8;backdrop-filter:blur(10px)}.r27-xprow{display:flex;justify-content:space-between;color:#9fb0c2;font-size:11px}.r27-xp{height:10px;margin-top:8px;border-radius:999px;background:#14273b;overflow:hidden;box-shadow:inset 0 2px 4px #0005}.r27-xp i{display:block;width:62%;height:100%;background:linear-gradient(90deg,#26eab7,#22a9ff);box-shadow:0 0 18px #20d9b174}
.r27-title{margin:3px 2px 4px;font-size:24px;font-weight:950;letter-spacing:-.03em}.r27-sub{margin:0 2px 15px;color:#92a8bf;line-height:1.4}.r27-filter{display:flex;gap:8px;overflow:auto;margin-bottom:13px;scrollbar-width:none}.r27-filter button{white-space:nowrap;padding:9px 12px;border:1px solid #29435f;border-radius:13px;background:#0b1929;color:#a4b5c7;font-weight:850}.r27-filter button.on{background:#0e8068;border-color:#26dcae;color:white}
.r27-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.r27-item{overflow:hidden;border:1px solid #2a425c;border-radius:20px;background:linear-gradient(180deg,#0e1e31,#091624);box-shadow:0 14px 34px #0006,inset 0 1px #ffffff08}.r27-item.legendary{border-color:#a57c23}.r27-item.epic{border-color:#8441be}.r27-item.rare{border-color:#247bb7}.r27-art{position:relative;aspect-ratio:1.13/1;background-image:linear-gradient(180deg,transparent,#07111ec7),url('rpg-catalog-v27.jpg');background-size:220% auto;background-repeat:no-repeat;overflow:hidden}.r27-art:after{content:'';position:absolute;inset:auto 8px 8px;height:1px;background:linear-gradient(90deg,transparent,#ffffff45,transparent)}.r27-art.crown{background-position:2% 0}.r27-art.hat{background-position:50% 0}.r27-art.staff{background-position:98% 0}.r27-art.cape{background-position:2% 47%}.r27-art.book{background-position:50% 47%}.r27-art.armor{background-position:98% 47%}.r27-art.boots{background-position:2% 94%}.r27-info{padding:10px}.r27-info h3{margin:0 0 6px;font-size:14px;line-height:1.25}.r27-pill{display:inline-block;padding:4px 7px;border-radius:999px;font-size:10px;font-weight:950;margin-bottom:6px}.legendary .r27-pill{background:#674a0b;color:#ffdc75}.epic .r27-pill{background:#592579;color:#efcfff}.rare .r27-pill{background:#0d4e79;color:#a9ddff}.r27-bonus{min-height:29px;color:#9cafc3;font-size:11px;line-height:1.35}.r27-equip{width:100%;margin-top:9px;padding:9px;border:1px solid #31516f;border-radius:11px;background:linear-gradient(180deg,#162a41,#102137);font-weight:900}.r27-equip.on{background:linear-gradient(135deg,#0c8d70,#19c099);border-color:#29dfb1}
.r27-sectionart{height:150px;margin-bottom:14px;border-radius:22px;border:1px solid #294560;background-image:linear-gradient(90deg,#071522ef,#07152255),url('rpg-progression-v27.jpg');background-size:cover;background-position:center;box-shadow:0 18px 45px #0006;display:flex;align-items:flex-end;padding:16px}.r27-sectionart b{font-size:21px}.r27-list{display:grid;gap:11px}.r27-row{display:flex;gap:12px;align-items:center;padding:14px}.r27-icon{width:48px;height:48px;border-radius:14px;border:1px solid #2e4b68;background:linear-gradient(145deg,#17314e,#0c1a2b);display:grid;place-items:center;font-weight:950;color:#33e9b7;box-shadow:inset 0 1px #ffffff12}.r27-grow{flex:1}.r27-grow b{display:block}.r27-grow small{color:#8fa5bc}.r27-progress{height:8px;margin-top:8px;border-radius:99px;background:#14263a;overflow:hidden}.r27-progress i{display:block;height:100%;background:linear-gradient(90deg,#22dfad,#21a8ff)}.r27-rank{display:grid;gap:9px}.r27-rankrow{display:grid;grid-template-columns:36px 43px 1fr auto;gap:10px;align-items:center;padding:12px}.r27-place{font-weight:950}.r27-avatarmini{width:42px;height:42px;border-radius:13px;background:linear-gradient(145deg,#1a3552,#0b1828);border:1px solid #294762;display:grid;place-items:center}.r27-power{color:#3ce8b8;font-weight:950}.r27-api{margin-top:12px;padding:11px 13px;border-radius:14px;border:1px solid #2b465f;background:#091827;color:#91a8bf;font-size:11px}.r27-api.ok{border-color:#15775f;color:#8ee6cf}.r27-api.bad{border-color:#8d3a3a;color:#ffb0b0}
@media(min-width:600px){.r27-grid{grid-template-columns:repeat(3,1fr)}}
'''

js = r'''(()=>{'use strict';
const ITEMS=[
{id:'crown',name:'Coroa Celestial',rar:'Lendário',tier:'legendary',bonus:'+20% XP · FOR +6 · DEF +6'},
{id:'hat',name:'Chapéu do Arquimago',rar:'Épico',tier:'epic',bonus:'+10% XP · MAG +5'},
{id:'staff',name:'Cajado Arcano',rar:'Lendário',tier:'legendary',bonus:'+20% XP · MAG +10'},
{id:'cape',name:'Manto das Estrelas',rar:'Épico',tier:'epic',bonus:'+10% XP · DEF +4'},
{id:'book',name:'Grimório Flutuante',rar:'Raro',tier:'rare',bonus:'+5% XP · MAG +3'},
{id:'armor',name:'Armadura do Campeão',rar:'Lendário',tier:'legendary',bonus:'+20% XP · FOR +8 · DEF +8'},
{id:'boots',name:'Chuteiras do Vento',rar:'Épico',tier:'epic',bonus:'+10% XP · VEL +8'}];
const KEY='ms_rpg27';let st={eq:'armor',coins:12450};try{st={...st,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch(e){};const save=()=>localStorage.setItem(KEY,JSON.stringify(st));
function itemCard(i){return `<article class="r27-item ${i.tier}"><div class="r27-art ${i.id}"></div><div class="r27-info"><h3>${i.name}</h3><span class="r27-pill">${i.rar}</span><div class="r27-bonus">${i.bonus}</div><button class="r27-equip ${st.eq===i.id?'on':''}" data-eq="${i.id}">${st.eq===i.id?'Equipado':'Equipar'}</button></div></article>`}
function hero(){const i=ITEMS.find(x=>x.id===st.eq)||ITEMS[5];return `<div class="r27-card r27-hero"><div class="r27-heroart"></div><div class="r27-scan"></div><div class="r27-level"><small>Nível</small><b>28</b></div><div class="r27-equipped"><small>Equipamento ativo</small><b>${i.name}</b><span class="r27-rarity">${i.rar}</span></div><div class="r27-stats"><div class="r27-stat for"><span>FORÇA</span><b>85</b></div><div class="r27-stat def"><span>DEFESA</span><b>72</b></div><div class="r27-stat vel"><span>VELOCIDADE</span><b>78</b></div><div class="r27-stat mag"><span>MAGIA</span><b>69</b></div></div><div class="r27-boost"><small>Boost ativo</small><b>+20% XP</b></div><div class="r27-xpbox"><div class="r27-xprow"><span>Progresso</span><span>1.240 / 2.000 XP</span></div><div class="r27-xp"><i></i></div></div></div><div id="r27Api" class="r27-api">Verificando conexão com dados de futebol…</div>`}
function panel(name){if(name==='player')return hero();if(name==='inventory')return `<h2 class="r27-title">Inventário</h2><p class="r27-sub">Itens com arte, raridade e atributos claros.</p><div class="r27-filter"><button class="on">Todos</button><button>Cabeça</button><button>Corpo</button><button>Relíquias</button><button>Chuteiras</button></div><div class="r27-grid">${ITEMS.map(itemCard).join('')}</div>`;if(name==='challenges')return `<div class="r27-sectionart"><b>Desafios diários</b></div><div class="r27-list">${[['3','Acertar 3 palpites','2 / 3','66'],['XP','Ganhar 250 XP','180 / 250','72'],['⚽','Acompanhar 5 jogos','4 / 5','80']].map(x=>`<div class="r27-card r27-row"><div class="r27-icon">${x[0]}</div><div class="r27-grow"><b>${x[1]}</b><small>${x[2]}</small><div class="r27-progress"><i style="width:${x[3]}%"></i></div></div></div>`).join('')}</div>`;if(name==='pass')return `<div class="r27-sectionart"><b>Passe de Batalha · Temporada 1</b></div><div class="r27-list">${[['28','Coroa Celestial','Pronto para resgatar'],['30','500 MatchCoins','Bloqueado'],['35','Manto das Estrelas','Bloqueado'],['40','Baú Épico','Bloqueado'],['50','Armadura do Campeão','Bloqueado']].map(x=>`<div class="r27-card r27-row"><div class="r27-icon">${x[0]}</div><div class="r27-grow"><b>${x[1]}</b><small>${x[2]}</small></div></div>`).join('')}</div>`;return `<h2 class="r27-title">Ranking</h2><p class="r27-sub">Temporada atual · Top 200.</p><div class="r27-rank">${[['1','JV Lenda','9.840'],['2','ReiDoGol','9.120'],['3','Mestre10','8.950'],['4','FutPro','8.410'],['5','TáticoBR','8.030']].map(x=>`<div class="r27-card r27-rankrow"><div class="r27-place">#${x[0]}</div><div class="r27-avatarmini">⚽</div><div><b>${x[1]}</b><small style="display:block;color:#91a5bc">Nível ${200-(+x[0]-1)*7}</small></div><div class="r27-power">${x[2]}</div></div>`).join('')}</div>`}
function render(name='player'){const c=document.querySelector('#msRpg27 .r27-content');if(!c)return;c.innerHTML=panel(name);if(name==='player')checkApi()}
async function checkApi(){const el=document.getElementById('r27Api');if(!el)return;const base='https://matchscope-kjf9.onrender.com';try{const r=await fetch(base+'/health',{cache:'no-store'});const j=await r.json().catch(()=>({}));if(r.ok&&j.ok){el.className='r27-api ok';el.textContent='Dados de futebol: conexão ativa.'}else throw new Error(j.error||'health inválido')}catch(e){el.className='r27-api bad';el.textContent='Dados de futebol indisponíveis no momento.'}}
function mount(){if(document.getElementById('msRpg27'))return;const el=document.createElement('section');el.id='msRpg27';el.innerHTML=`<div class="r27-shell"><header class="r27-top"><div class="r27-brand"><div class="r27-logo">M</div><div class="r27-brandtext"><b>MatchScore</b><small>Futebol • dados • inteligência</small></div><div class="r27-wallet"><i class="r27-coin"></i>${Number(st.coins||0).toLocaleString('pt-BR')}</div></div><div class="r27-headline"><h1>Meu jogador</h1><span class="r27-badge">BETA 27</span><button class="r27-close">×</button></div></header><nav class="r27-tabs">${[['player','Jogador'],['inventory','Inventário'],['challenges','Desafios'],['pass','Passe'],['ranking','Ranking']].map((x,n)=>`<button class="r27-tab ${n?'':'on'}" data-panel="${x[0]}">${x[1]}</button>`).join('')}</nav><main class="r27-body"><div class="r27-content"></div></main></div>`;document.body.appendChild(el);render();el.addEventListener('click',e=>{const t=e.target.closest('[data-panel]');if(t){el.querySelectorAll('.r27-tab').forEach(b=>b.classList.toggle('on',b===t));render(t.dataset.panel)}const q=e.target.closest('[data-eq]');if(q){st.eq=q.dataset.eq;save();render('inventory')}if(e.target.closest('.r27-close'))el.remove()})}
function boot(){document.addEventListener('click',e=>{const a=e.target.closest('button,a,[role=button]');if(a&&/meu jogador/i.test(a.textContent||''))setTimeout(mount,80)},true);if(/meu jogador/i.test(document.body.innerText||''))setTimeout(mount,1000)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();})();'''

(root / 'beta-v27.css').write_text(css, encoding='utf-8')
(root / 'beta-v27.js').write_text(js, encoding='utf-8')
h = index.read_text(encoding='utf-8')
if 'beta-v27.css' not in h:
    h = h.replace('</head>', '<link rel="stylesheet" href="beta-v27.css?v=27"></head>')
if 'beta-v27.js' not in h:
    h = h.replace('</body>', '<script src="beta-v27.js?v=27"></script></body>')
index.write_text(h, encoding='utf-8')
print('Beta 27 profissional aplicada com artes e detalhes graficos')
